func withLogging(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        start := time.Now()                          // pre
        next.ServeHTTP(w, r)                         // target or next middleware
        log.Printf("%s %s %s", r.Method, r.URL.Path, time.Since(start))   // post
    })
}
